const brief=document.querySelector('#brief-dialog');
const projectDialog=document.querySelector('#project-dialog');
function showDialog(dialog){dialog.showModal();document.body.style.overflow='hidden';}
function openBrief(){if(projectDialog.open)projectDialog.close();showDialog(brief);}
document.querySelectorAll('[data-brief]').forEach(b=>b.addEventListener('click',openBrief));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow='';});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
document.querySelectorAll('[data-whatsapp-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const idea=String(data.get('idea')||'').trim();if(idea.length<8){form.querySelector('[name="idea"]').focus();return;}const name=String(data.get('name')||'').trim();const business=String(data.get('business')||'').trim();const lines=['Olá, WebUp! Quero conversar sobre o site gratuito e o primeiro mês de teste.','',...(name?['Meu nome: '+name]:[]),...(business?['Meu negócio: '+business]:[]),'Minha ideia: '+idea,'','Depois do teste, podemos avaliar os custos de manutenção.'];window.open('https://wa.me/5555984332637?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener,noreferrer');}));
const concepts=[{name:'Fio — Barbearia',description:'Um conceito de site para barbearias que combina personalidade, apresentação dos serviços e um caminho direto para agendar pelo WhatsApp. Verde profundo, tipografia expressiva e uma identidade que valoriza o estilo.',tags:['Site institucional','Design responsivo','Contato pelo WhatsApp']},{name:'Forma — Arquitetura',description:'Um conceito editorial para apresentar espaços com intenção. Tons naturais, composições amplas e uma experiência que valoriza cada projeto antes de convidar o visitante para uma conversa.',tags:['Portfólio autoral','Direção de arte','Experiência responsiva']},{name:'Grão — Café de origem',description:'Um conceito de presença digital que aproxima o visitante da marca. Cores quentes, personalidade e espaço para contar a história do produto, apresentar o cardápio e facilitar o contato.',tags:['Landing page','Identidade digital','Apresentação de produtos']}];
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const data=concepts[Number(button.dataset.project)];const target=document.querySelector('#project-detail');target.replaceChildren(button.querySelector('.project-art').cloneNode(true));const text=document.createElement('div');text.className='detail-copy';text.innerHTML=`<p class="eyebrow">ESTUDO DE DESIGN · MARCA FICTÍCIA</p><h2 id="project-title">${data.name}</h2><p>${data.description}</p><div class="detail-tags">${data.tags.map(t=>`<span>${t}</span>`).join('')}</div><button class="button primary">Quero um site nessa direção <span>↗</span></button>`;text.querySelector('button').addEventListener('click',()=>{openBrief();document.querySelector('#brief-form [name="idea"]').value=`Gostei do conceito ${data.name} e quero algo nessa direção para meu negócio.`;});target.append(text);showDialog(projectDialog);}));
document.querySelector('#year').textContent=new Date().getFullYear();
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
window.webupMotion=!reduced.matches;
const toggle=document.querySelector('#motion-toggle');
function setMotion(enabled){window.webupMotion=enabled;document.body.classList.toggle('motion-paused',!enabled);toggle.setAttribute('aria-pressed',String(!enabled));toggle.textContent=enabled?'Pausar movimento Ⅱ':'Ativar movimento ▷';window.dispatchEvent(new CustomEvent('webup:motion',{detail:enabled}));}
toggle.addEventListener('click',()=>setMotion(!window.webupMotion));reduced.addEventListener('change',e=>setMotion(!e.matches));setMotion(!reduced.matches);
